"""Project terminal saved evidence into HTML; no scientific imports or search."""
import gzip
import hashlib
import html
import json
import os
import shutil
import subprocess
from decimal import Decimal
from pathlib import Path
from report_evidence import ROOT, PUB, PREFIX, DEST, pin, load, project

HERE = Path(__file__).resolve().parent
MAIN = 'docs/research/gcts-rl-renewal/index.html'
BASE = '94aa6e1fd87b09dae6651385bb661cfc802dd42e'
PHASE = ROOT / '.gcts-active/family-proposal-source-20261012'


def math(value):
    return r'\(' + html.escape(str(value)) + r'\)'


def table(headers, rows):
    return '<div class="table-scroll"><table><thead><tr>' + ''.join('<th>'+html.escape(x)+'</th>' for x in headers) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows) + '</tbody></table></div>'


def main():
    terminal = load(HERE/'preparation-terminal-v2.json')
    assert terminal['owner_terminal']['exit_code'] == 0 and terminal['worker_reaped'] and terminal['supervisor_reaped']
    outcome, lifetime = load(PHASE/'preparation-outcome-v2.json'), load(PHASE/'preparation-lifetime-v2.json')
    assert lifetime['status'] == 'passed_family_preparation_full_lifetime_resource_phase'
    assert outcome['status'] == 'complete_declared_proposal_grammar_prepared_pending_independent_audit'
    evidence_path = ROOT/outcome['evidence']['path']
    assert pin(evidence_path) == {k:outcome['evidence'][k] for k in ('sha256','bytes')}
    with gzip.open(evidence_path,'rt') as f: evidence = json.load(f)
    plan = load(PHASE/'preparation-plan-v2.json')
    fixture = load(HERE/'fixture-terminal.json')
    baseline = subprocess.check_output(['git','show',BASE+':'+MAIN],cwd=PUB)
    assert (HERE/'baseline-index.html').read_bytes() == baseline
    historical = {(MAIN,hashlib.sha256(baseline).hexdigest()):HERE/'baseline-index.html'}
    for commit,label in [('a4adb7b113338e6b8753b880356954b6a26d2086','106'),('f41da478a4a16b4c91eabe20aa8255ebdfc30830','105')]:
        content = subprocess.check_output(['git','show',commit+':'+MAIN],cwd=PUB)
        p = HERE/('historical-index-'+label+'.html')
        if p.exists(): assert p.read_bytes() == content
        else: p.write_bytes(content)
        historical[(MAIN,hashlib.sha256(content).hexdigest())] = p
    historical[('.gcts-active/receptor-matching-geometry-independent-20261011/positive_certificate_oracle_v1.py','7ed3f345f8938bdf465d72033f52972314db5e303f93066fdb20840d4f3f67c7')] = ROOT/'.gcts-active/receptor-matching-geometry-independent-20261011/positive_certificate_oracle_draft_7ed3f345.py'
    excluded = {'publication.json','publication-staging.json','task-files.json','turn-result.json','local-validation.json','live-hash-checks.json','browser-validation.json','staged-whitespace-check.json','baseline-index.html','historical-index-105.html','historical-index-106.html','stage_publication.py','verify_live_files.py','final-review.json'}
    folders = [('.gcts-active/family-proposal-source-20261012','producer',set()),
               ('.gcts-active/family-proposal-independent-20261012','independent-fixtures',set()),
               ('.gcts-active/family-proposal-learning-20261012','learning',set()),
               ('.gcts-active/family-preparation-source-independent-review-20261012','independent-source-review',set()),
               (str(HERE.relative_to(ROOT)),'coordinator',excluded)]
    files,origins,bindings = project(folders,historical)
    def save(name,value):
        p=DEST/name;p.write_text(json.dumps(value,indent=2,allow_nan=False)+'\n');files.add(str(p.relative_to(ROOT)))
    def link(origin,label):
        row=next((e for e in origins if e['origin']==origin),None)
        if row: target=row['path']
        else:
            row=next(e for e in bindings if e['path']==origin);assert row['archive_member'] is None
            target=row['published_path']
        return '<a href="'+html.escape(os.path.relpath(target,PREFIX))+'">'+html.escape(label)+'</a>'
    modelpin=next(p for p in plan['inputs'] if p['role']=='primitive_model')
    with gzip.open(ROOT/modelpin['path'],'rt') as f: model=json.load(f)
    assert model['formula_codes']==evidence['formula_codes']
    formulas=model['formula_codes']; recipes=model['recipes']; groups=[]
    for g in evidence['groups']:
        rows=[]
        keys=[a['key'] for a in evidence['root_anchors']]+g['members']
        ids={json.dumps(k):v for k,v in zip(g['members'],g['full_member_ids'])}
        for k in sorted(keys,key=lambda k:k[1]):
            recipe,row,refs=k; primitive=recipes[recipe]; witness=primitive['primitive_witness']
            code=formulas.index(witness['formula'])
            owners=[i+1 for i,c in enumerate(g['components']) if k in c['members']]
            original=not owners
            rows.append(dict(row=row,code=code,formula=formulas[code],refs=refs,rule=witness['rule'],input_codes=[formulas.index(f) for f in primitive['ordered_premise_formulas']],key=k,full_id=ids.get(json.dumps(k),next((a['full_id'] for a in evidence['root_anchors'] if a['key']==k),None)),primitive_command=witness,components=owners,original_hypothesis=original))
        groups.append(dict(label='Pool '+str(g['pool_index'])+' · '+('single' if len(g['components'])==1 else 'pair')+' · '+str(g['distinct_member_count'])+' placements · '+str(g['shared_member_count'])+' shared',rows=rows,raw=g))
    save('visual-data.json',dict(scope='Saved preparation proposals and original hypotheses only; no execution as hints, proof acceptance or learned action.',groups=groups,evidence=outcome['evidence'],model_input=modelpin))
    viewer=HERE/'viewer.js';shutil.copyfile(viewer,DEST/'viewer.js');files.add(PREFIX+'viewer.js')
    origins.append(dict(origin=str(viewer.relative_to(ROOT)),path=PREFIX+'viewer.js',**pin(viewer)))
    bindings.append(dict(path=str(viewer.relative_to(ROOT)),**pin(viewer),published_path=PREFIX+'viewer.js',archive_member=None))
    save('origins.json',origins);save('source-input-bindings.json',bindings)
    c=evidence['counters']; small={k:v for k,v in c.items() if k not in ('type_visits','rejected_binding_records')}
    total=Decimal(str(fixture['owner_seconds_before_final_receipt_write']))+Decimal(str(lifetime['full_supervisor_process_seconds_including_receipt_write']))
    census=table(['Measured preparation','Count'],[[label,math(c[key])] for label,key in [('Checked source interfaces','interfaces_checked'),('Single types visited','single_types_visited'),('Ordered pair types visited','pair_types_visited'),('Connected receptor bindings visited','binding_tuples_visited'),('Registered proposals','registered_groups'),('Component member occurrences, summed over proposals','source_member_occurrences'),('Distinct members, summed over proposals','group_distinct_members'),('Shared members, summed over proposals','group_shared_members')]])
    group_table=table(['Pool index','Components','Occurrences','Distinct placements','Shared placements','Declared output rows'],[[math(g['pool_index']),math(len(g['components'])),math(g['component_member_occurrences']),math(g['distinct_member_count']),math(g['shared_member_count']),math('('+','.join(str(c['conclusion_row']) for c in g['components'])+')')] for g in evidence['groups']])
    costs=table(['Owned stage','Seconds','Conservative peak bytes','Meaning'],[
        ['Independent pure fixtures',math(fixture['owner_seconds_before_final_receipt_write']),math(fixture['conservative_peak_bytes']),'Synthetic mechanics; no actual model'],
        ['Cold proposal preparation',math(lifetime['full_supervisor_process_seconds_including_receipt_write']),math(lifetime['conservative_host_peak_bytes']),'Input verification, model/body loading, complete enumeration, compilation, serialization and reaping'],
        ['Additional owned total',math(total),'Peaks are not added','Source authoring, metadata freezes, reviews, report and publication are additional']])
    config={'tex':{'inlineMath':[[r'\(',r'\)']],'displayMath':[[r'\[',r'\]']]},'options':{'skipHtmlTags':['script','style','pre','code']}}
    content='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Receptor-adapted cluster proposals · GCTS research</title><link rel="stylesheet" href="../report.css"><script>window.MathJax='''+json.dumps(config)+''';</script><script defer src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml.js"></script><style>
main{max-width:1280px}.note{padding:18px;border-left:4px solid #a57334;background:#fff4e3}.controls{display:flex;flex-wrap:wrap;gap:18px;margin:20px 0}select{font:inherit;padding:9px;max-width:100%}.tile-line{display:grid;grid-template-columns:220px minmax(0,1fr);gap:24px;align-items:start;padding:20px 0;border-bottom:1px solid #d4dcd2}.square{aspect-ratio:1;box-sizing:border-box;padding:12px;display:flex;flex-direction:column;justify-content:space-around;background:#fff;border:2px solid #4c654d;border-radius:4px;font-size:14px}.blue-layer{color:#174e9a;background:#edf4ff;border-left:4px solid #4e82c1;padding:5px}.purple-layer{color:#693791;background:#f3edff;border-left:4px solid #7954aa;padding:5px}.row-text{min-width:0}.math{display:inline-block;max-width:100%;overflow:auto;vertical-align:middle}.row-text>.math{font-size:18px}.membership{font-size:13px;color:#596751}pre{font-size:12px;max-height:340px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}.hierarchy{display:flex;flex-wrap:wrap;gap:16px;margin:20px 0}.component-card{flex:1;min-width:230px;padding:15px;border:2px solid #6d7c6b;background:#f6faf4;display:flex;flex-direction:column;gap:12px}.component-card small{font-size:10px;overflow-wrap:anywhere}[hidden]{display:none!important}td{font-size:14px}@media(max-width:700px){.tile-line{grid-template-columns:1fr}.square{width:220px}}
</style></head><body><header class="masthead"><a href="../#family-proposals">Research report</a><span>NOTEBOOK 108</span><a href="#reader">Tile reader</a></header><main><section class="intro"><p class="eyebrow">THREE PARALLEL TRACKS · ONE OWNED PREPARATION RUN</p><h1>Fit a family to its receptors.</h1><p class="deck">The existing checked inventory now produces single and paired clusters automatically for the original hypotheses. The saved proposals expose their primitive squares, distant markings, sharing and formulas.</p><p><a href="#results">Actual preparation</a> · <a href="#reader">Colored tiles and formulas</a> · <a href="#learning">Learning readiness</a> · <a href="#cost">Full costs</a></p></section><section class="panel" id="results"><h2>Five proposals from the complete declared grammar.</h2><p class="note">This is completed proposal preparation, pending the independent actual-pool audit. No search hint has been executed, no new theorem has been admitted, and no RL training occurred in this phase.</p>'''+census+group_table+'''<p>The complete type domain was visited; most types have no matching original-root receptors. The five connected bindings produced three singles and two pairs, with no rejected connected binding. The generator also counted '''+math(c['disconnected_second_bindings_outside_grammar'])+''' disconnected second-component bindings outside the declared grammar. These are not proof-pruning failures.</p><p>The largest pair contains '''+math(26)+' component occurrences and '+math(21)+''' distinct primitive placements. Its shared prefix uses the same full placement keys and identities. Together with the '''+math(3)+''' original hypothesis squares, its proposed occupancy fits the '''+math(24)+'''-row region. Fitting and registering a proposal does not establish a complete executing proof.</p></section><section class="panel" id="method"><h2>What was generated.</h2><p>Every first-component receptor binds an actually selected original hypothesis. A second component may also bind the explicitly declared output of the included first component; at least one such connection is required. That output remains an obligation inside the proposed union. It is not added to the hypothesis list.</p><p>For each exact ordered binding, the generator preserves source-member order, reuses an earlier identical placement when legal, and otherwise chooses the earliest free row after its required sources. Component occurrences stay visible even when the union counts an identical placement once. Formula equality alone cannot authorize occupancy sharing.</p><p>This finite proposal grammar uses the full '''+math(171)+'''-family checked inventory, at most two components, and one canonical embedding per binding. It does not generate every compatible cluster, every embedding, new lemmas or unrestricted first-order proofs. Source bodies and the finite '''+math(229)+'-recipe, '+math(217)+'''-formula language are existing infrastructure. The generator decoded and discarded the old projection example; no authored target-proof word was used as a hint.</p><p>One immutable descriptor represents the entire union. The forthcoming search adapter must revalidate it against the complete global point graph, allow forced moves to interrupt it, retain every base alternative, retire incompatible hints and restore the paired state exactly on rollback. Those execution checks were not run here.</p></section><section class="panel" id="reader"><h2>Read each proposed square as a formula.</h2><p>The squares translate without rotation. Blue markings encode the output formula and the required formula values at distant source rows; purple markings encode ordered source offsets. The formula beside each tile is a direct decoding of its saved primitive command. Original hypotheses appear first. Component cards show input rows and the declared output row; their union has one occupancy contribution for a shared square.</p><p>These remain symbolic Hilbert-incidence statements. Point, line and incidence are predicates in the declared theory; a drawing of physical points or lines does not participate in checking. Arithmetic remains a separate benchmark family using the shared proof language.</p><div class="controls"><label>Proposal <select id="group"></select></label><label><input id="blue" type="checkbox" checked> Blue formula layer</label><label><input id="purple" type="checkbox" checked> Purple source layer</label></div><div id="group-view" aria-live="polite"></div></section><section class="panel" id="checks"><h2>Evidence and contract gaps.</h2><p>The independent pure oracle passed '''+math(52)+' controls: '+math(18)+' positive and '+math(34)+''' negative. They cover ordered ports, non-last declared conclusions, aliases, canonical embedding, exact identity sharing, unit capacity, distant conflicts and malformed values. These synthetic results do not establish producer correspondence on the actual model.</p><p>Independent source review verified the five frozen sources, all '''+math(151)+' input roles, '+math(770)+' preserved records and '+math(776)+''' unique paths. ROOT separately reviewed the full code and bound prerequisites before one owned run. The actual-pool auditor is the next distinct gate; source and synthetic checks cannot replace it.</p><p>The producer reports an unchanged initial/final graph semantic digest. Its only placements are the three original hypotheses; attempts, forced moves, branches and backtracks stay zero. Candidate validation and full-identity construction still incur real work. The point-model adaptation retains complete candidate domains, global dead-end checks, global forced propagation and earliest-generation branching, with degree used only for generation ties. No Controller or Executor was constructed in this preparation phase, so runtime conformance of the new proposal bridge is unestablished.</p><p>Fixed symbolic markings retain their exact formula/reference meanings. Learned geometric failure markings, an open irregular-cluster constructor, movable boundaries and new lemma discovery remain research tasks. A partial or absent proposal cannot justify logical pruning.</p></section><section class="panel" id="learning"><h2>The next learning experiment is defined, not trained.</h2><p>The parallel learning track has frozen a first selector design: choose a ready whole proposal or choose the NULL action, using structural and completion features. NULL must suppress proposal preference in the executable adapter; immutable priorities cannot be changed to simulate a policy. The selection state must share the graph's rollback boundary.</p><p>Its source includes an epsilon-mixture policy, a saved-draw selection function, score-gradient calculation and a clipped episode update. Numeric functions, RNG draws, features, donor models and training have not been executed or prepared as an activated experiment. Python annotation compatibility and probability-input validation were repaired in preserved successor sources before any import.</p><p>The prospective comparison holds proposal availability, primitives, original hypotheses, scheduler and resource semantics fixed between baseline, untrained and trained lanes. Reward must use dependency-complete facts, avoid rewarding pending output marks or rollback rediscovery, and remain provisional until independent certificate checks. Held-out theorem trajectories must stay out of tuning and mining. This first lane would learn proposal selection; learning new cluster topology and reusable lemmas is a later experiment.</p><p>'''+link('.gcts-active/family-proposal-learning-20261012/protocol-v2.json','Frozen learning protocol')+' · '+link('.gcts-active/family-proposal-learning-20261012/readiness-v2.json','Source-only readiness')+' · '+link('.gcts-active/family-proposal-independent-20261012/protocol-assessment-v1.json','Independent protocol assessment')+'''</p></section><section class="panel" id="cost"><h2>Cold preparation and independent checking are charged.</h2>'''+costs+'''<p>Preparation alone, including actual model and original body setup, costs '''+math(outcome['preparation_seconds_including_model_and_body_setup'])+''' seconds inside the longer owner. Enumeration, embedding, validation and registration timers overlap; they are not additional disjoint bills. The owner includes worker/supervisor serialization and reaping, with its own final receipt write explicitly outside the pre-write clock.</p><p>The declared preparation deadline is '''+math(30)+' seconds, with '+math(60)+'-second child, '+math(65)+'-second supervisor and '+math(70)+'-second outer gates, and '+math(536870912)+''' conservative peak bytes. Child alarms, sampled owned-process monitoring and final kernel-peak rejection do not constitute a hard operating-system memory cap. No partial active pool is exposed if enumeration remains unknown.</p><p>The previous matching phase adds '''+math('50.956800624')+' owned seconds, and its predecessor adds '+math('50.405773542')+''' under separate owners. Earlier inventory, native preparation and failed gates remain additional. Current source authoring CPU time is unmeasured; static hash/AST freezing is separately recorded and does not count as a scientific run. Preserved V1 and pre-freeze drafts were corrected before execution, so they are source defects, not actual failed searches.</p></section><section class="panel" id="assessment"><h2>A useful hierarchy step, with effectiveness still open.</h2><p>Automatic receptor binding and exact shared expansion now yield a small concrete proposal pool from the full existing inventory. That is progress toward the proposed multiscale hierarchy. It does not yet show a GCTS or RL proof-search advantage: the last primitive controls remain unknown, and this phase performs no new search. The next comparison must include cold preparation, actual-pool checking, execution, training and certificate costs.</p><p>The three agents divide source construction, independent checking and learning design; ROOT owns current activation, actual process lifetimes, integration and publication. Independent disagreement can stop a gate without erasing the other work. The broader research goal remains active.</p></section><section class="panel" id="evidence"><h2>Inspect the saved records.</h2><p>'''+link(str((PHASE/'preparation-outcome-v2.json').relative_to(ROOT)),'Actual outcome')+' · '+link(str((PHASE/'preparation-evidence-v2.json.gz').relative_to(ROOT)),'Complete raw preparation tape')+' · '+link(str((PHASE/'preparation-lifetime-v2.json').relative_to(ROOT)),'Full owner lifetime')+' · '+link('.gcts-active/family-proposal-independent-20261012/fixture-result-v2.json','All synthetic controls')+' · '+link('.gcts-active/family-preparation-source-independent-review-20261012/source-review-v2.json','Independent source review')+'''</p><p><a href="visual-data.json">Viewer projection</a> · <a href="result-summary.json">Exact result summary</a> · <a href="origins.json">Exported origins</a> · <a href="source-input-bindings.json">Source and historical routes</a> · <a href="external-runtime-bindings.json">Runtime identity prerequisites</a> · <a href="sources-and-inputs.zip">Additional bound sources and history</a></p><p>Runtime binaries are excluded from the export; their identities are recorded separately. The reader displays saved evidence and does not run a checker or establish validity.</p></section></main><script defer src="viewer.js"></script></body></html>'''
    (DEST/'reader.html').write_text(content);files.add(PREFIX+'reader.html')
    save('result-summary.json',dict(status=outcome['status'],goal_status='active',counters=small,groups=[{k:g[k] for k in ('pool_index','fixed_priority','distinct_member_count','component_member_occurrences','shared_member_count')} for g in evidence['groups']],single_groups=sum(len(g['components'])==1 for g in evidence['groups']),pair_groups=sum(len(g['components'])==2 for g in evidence['groups']),new_owned_seconds=str(total),preparation_lifetime=lifetime,fixture_terminal=fixture,actual_pool_audit='pending',new_target_searches=0,new_accepted_proofs=0,new_training=False,source_authoring_seconds=None,report_scientific_execution=False))
    previous=baseline.decode();assert 'RESEARCH NOTEBOOK · 107' in previous
    panel='<section class="panel" id="family-proposals"><h2>Checkpoint 108 · Automatic receptor-adapted cluster proposals</h2><p>The complete declared single/pair type domain now yields '+math(5)+' proposals from the existing '+math(171)+'-family inventory, in '+math('3.611774')+' owned seconds. The largest pair shares '+math(5)+' primitive placements. Independent synthetic controls and source review pass; the actual-pool audit remains pending. <a href="family-proposals/reader.html?v=20261012-fp1#reader">Inspect the colored squares, formulas and component interfaces</a>.</p><p>This phase prepares proposals only. It executes no search, admits no new proof and trains no RL policy. The broader research program remains active.</p></section>\n'
    anchor='<section class="panel" id="receptor-matching">';assert previous.count(anchor)==1
    updated=previous.replace('RESEARCH NOTEBOOK · 107','RESEARCH NOTEBOOK · 108',1).replace(anchor,panel+anchor,1)
    old='Three agents work on arithmetic induction, symbolic Hilbert incidence, and external automated provers. Each owns its sources, frozen inputs, measured searches and independent audits. The coordinator integrates the evidence and publishes the readers. The shared native Wang checker remains unchanged; search hints never authorize an invalid proof.'
    new='Three agents work on arithmetic and learning design, symbolic Hilbert-incidence cluster construction, and independent checking with external prover controls. In the current proposal phase they prepare sources and reviews in parallel; the coordinator owns activation, actual measured runs, integration and publication. Earlier agent-owned experiments retain their separate receipts. The shared native Wang checker remains unchanged; search hints never authorize an invalid proof.'
    assert old in updated;updated=updated.replace(old,new,1)
    current=ROOT/MAIN
    if current.read_bytes()!=baseline:
        record=next(e for e in load(HERE/'task-files.json') if e['path']==MAIN)
        assert pin(current)=={k:record[k] for k in ('sha256','bytes')},'unrelated report edit'
    current.write_text(updated);files.add(MAIN)
    manifest=[dict(path=f,**pin(ROOT/f)) for f in sorted(files)]
    (HERE/'task-files.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print(json.dumps(dict(files=len(manifest),origins=len(origins),bindings=len(bindings),groups=len(groups),report_scientific_execution=False)))


if __name__=='__main__':main()
